"""Build one ready-made resin charm project guide from existing catalog facts."""
import html, json, re
from pathlib import Path
from urllib.parse import urlencode

ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://www.qulacrafts.com/'
SLUG = 'guide-ready-made-resin-charms-diy-projects.html'
TITLE = 'DIY Projects with Ready-Made Resin Charms'
DESCRIPTION = 'Make hair clips, bag charms and gift decorations with ready-made resin charms. Compare real SKUs, size references and packing, then plan your samples.'
DATE = '2026-11-08'
CATALOG = json.loads((ROOT/'assets/data/product-catalog.json').read_text())
PRODUCTS = {p['sku']: p for c in CATALOG['categories'] for p in c['products']}
FACTS = {
 'RW22372': ('Resin cookie flatbacks', '21 mm source reference', '100 pieces per bag', 'Standard bag: random mixed designs and colors; individual designs or colors cannot be selected.'),
 'RW4252': ('Resin jelly bean decorations', '12 × 22 mm', '100 pieces per bag', 'Assorted candy colors. Confirm the reverse side and fixing method for your chosen project.'),
 'RW26898': ('Polka-dot resin bows', 'Approx. 17 × 26 mm', '100 pieces per bag', 'Confirm the assortment, reverse side and fixing method. A hole or fitting is not established.'),
 'CDK070': ('Metal split key rings', '30 mm ring reference', '100 pieces per bag', 'Hardware only. Confirm the connection and finish; a complete charm assembly is not included.')
}
esc = lambda value: html.escape(str(value), quote=True)

def inquiry(sku, project):
 p = PRODUCTS[sku]
 params = dict(sku=sku, product=p['title'], image=p['image'], category=('Keychains' if p['category']=='Keychain' else p['category']),
               source='ready-made-resin-diy', entry_page='/'+SLUG,
               application=project+'; catalog reference: '+BASE+p['pdp'])
 return 'quote.html?'+urlencode(params)

def card(sku, project):
 p=PRODUCTS[sku]; label,size,pack,note=FACTS[sku]
 return f'''<article class="resin-diy-product" data-diy-sku="{sku}"><a href="{p['pdp']}"><img src="{p['image']}" alt="{esc(p['imageAlt'])}" width="{p['imageWidth']}" height="{p['imageHeight']}" loading="lazy" decoding="async"></a><div><span class="eyebrow">{sku}</span><h3><a href="{p['pdp']}">{esc(label)}</a></h3><dl><dt>Size reference</dt><dd>{esc(size)}</dd><dt>Packing reference</dt><dd>{esc(pack)}</dd></dl><p>{esc(note)}</p><a class="text-link" href="{p['pdp']}">View {sku} details →</a><a class="btn btn-primary" data-diy-inquiry="{sku}" href="{esc(inquiry(sku,project))}">Ask about {sku}</a></div></article>'''

body = '''<section class="page-hero"><div class="container narrow"><nav class="breadcrumb"><a href="index.html">Home</a> / <a href="resources.html">Resources</a> / <span>Ready-Made Resin Charm Projects</span></nav><span class="eyebrow">DIY Projects · Materials &amp; Selection</span><h1>DIY Projects with Ready-Made Resin Charms</h1><p>Turn finished decorative pieces into hair accessories, bag details and personal gifts. Start with a small layout and check how each piece will attach.</p><p class="small-note">Published November 8, 2026 · Qula Craft</p></div></section>
<section class="section" style="padding-top:24px"><article class="container guide-body resin-diy-guide">
<div class="answer-box"><strong>What can you make with ready-made resin charms?</strong> Use suitable pieces to decorate hair clips, keychain or bag-charm bases, gift tags, keepsake boxes, bookmarks and photo frames. Match the charm's size, reverse side and weight to the base. A flatback decoration needs a suitable bonding surface; a hanging design needs a confirmed hole, loop or separate carrier.</div>
<p>A small charm can set the whole direction of a project: a cookie for a bakery-themed clip, a bright candy shape beside a bag strap, or a bow on a gift tag. The useful starting point is the finished object and the way it will be handled. Choose the decorative pieces after you know where they will sit.</p>
<nav class="resin-diy-nav" aria-label="Choose a resin charm project"><a href="#hair-clips">Hair clips</a><a href="#bag-charms">Bag charms &amp; keychains</a><a href="#gift-decorations">Gift decorations</a><a href="#compare-materials">Compare materials</a></nav>
<section id="before-you-start"><h2>Choose the attachment before the color palette</h2><p>For a glue-on project, ask for a clear reverse-side image and check the actual contact area against your base. A rounded miniature may need a different support from a flatback cabochon. For a hanging project, confirm the hole or loop and its dimensions, or select a carrier designed to hold a decorative piece. A product name containing “charm” does not establish an attachment.</p><p>Set out the base, decorative piece and any hardware together. Check that moving parts can open, that the decoration does not cover an edge that must flex, and that the finished object remains comfortable to use. Follow the adhesive or base manufacturer's instructions for the exact materials. Review the assembly on a sample before repeating it for a collection.</p></section>
<section id="hair-clips"><h2>1. Make a cookie-themed hair clip</h2><p>One small focal decoration can be enough for a simple clip. RW22372 is a resin cookie flatback assortment with a 21 mm source size reference. Its supplied front-and-reverse photograph helps you discuss the bonding area; individual mixed-piece dimensions and thickness still need sample confirmation.</p><ol><li><strong>Plan the position.</strong> Lay one piece on the closed clip or a suitable decorative mounting base. Keep the hinge, spring and gripping surfaces clear.</li><li><strong>Check a full opening cycle.</strong> Open and close the clip while holding the decoration in the proposed position. Confirm the contact area and fixing method before bonding.</li><li><strong>Assemble and inspect a sample.</strong> Follow the base and adhesive instructions, then check the result before making a matching set.</li></ol><p>The standard RW22372 bag contains random mixed designs and colors. It cannot guarantee two identical cookies for a pair. If matching pairs are central to your project, describe that requirement before ordering and ask whether a separate arrangement is feasible.</p>[[COOKIE_CARD]]</section>
<section id="bag-charms"><h2>2. Build a bag charm or keychain around a suitable carrier</h2><p>A colorful resin piece can provide a focal detail, but the connection must suit the way a bag or set of keys will move. For a piece without a confirmed hole or loop, use an appropriate mounting base or carrier rather than assuming a jump ring can pass through it. Confirm carriers, clasps, chain and other assembly parts separately.</p><ol><li><strong>Choose the route to the key ring.</strong> List every connection: decoration to carrier, carrier to connector, and connector to ring or clasp.</li><li><strong>Check the hardware dimensions.</strong> CDK070 has a 30 mm ring reference. That number alone does not establish the usable opening, connector clearance or compatibility with a particular charm.</li><li><strong>Review the assembled sample.</strong> Check that connections close correctly and the decoration does not catch on the bag or interfere with keys. Ask for any missing connection dimensions before ordering in quantity.</li></ol><p>RW4252 jelly bean decorations offer a 12 × 22 mm size reference for comparing a candy-themed layout. Review their reverse side and fixing method before selecting them for the carrier. CDK070 is sold as ring hardware; the two product records do not establish a preassembled or tested combination.</p><div class="resin-diy-grid">[[CANDY_CARD]][[RING_CARD]]</div><p>For a hardware-led project, continue to the <a href="keychain.html">keychain components catalog</a>. For a jewelry project, compare the <a href="jewelry-accessories.html">jewelry findings range</a> and confirm the actual attachment dimensions.</p></section>
<section id="gift-decorations"><h2>3. Add a resin bow to a gift tag, box or frame</h2><p>A bow motif gives a gift a clear focal point without requiring a crowded layout. RW26898 is a polka-dot resin bow decoration with an approximate 17 × 26 mm size reference. Check the selected piece against the usable area of your tag, box lid or frame border.</p><ol><li><strong>Mark the usable area.</strong> Leave room for the name, message, lid opening or photograph. Test the position with the actual decoration before fixing it.</li><li><strong>Choose one supporting detail.</strong> A ribbon, printed card or small accent can repeat a color from the bow. Confirm those materials separately from the resin SKU.</li><li><strong>Review handling and packing.</strong> Check that the decoration sits securely on the chosen surface and that the gift can be packed without pressure on the raised piece.</li></ol><p>For a bookmark, keep any raised decoration clear of the part that sits between the pages. For a frame, keep it outside the photograph and any opening mechanism. A supplied decoration is a component: the finished gift, base and styling materials depend on your project.</p>[[BOW_CARD]]<p>For more seasonal ideas, see <a href="blog-christmas-gifts-for-family-diy.html">DIY Christmas gifts to make with family</a>. For a dense phone-case layout, use the separate <a href="guide-decoden-supplies.html">decoden supplies guide</a>.</p></section>
<section id="compare-materials"><h2>Compare these project materials before requesting a quote</h2><div class="resin-diy-table" role="region" aria-label="Resin project material comparison" tabindex="0"><table class="spec-table"><thead><tr><th>Reference</th><th>Size reference</th><th>Packing reference</th><th>Check for your project</th></tr></thead><tbody>[[FACT_ROWS]]</tbody></table></div><p>These are source specification and packing references, not new physical measurements. “100 pieces per bag” describes the pack, not the minimum order. Confirm current availability, MOQ, packing, any assortment requirements and timing in your quotation. RW22372's standard mixed bag does not allow individual design or color selection.</p></section>
<section id="plan-a-kit"><h2>Turn one successful sample into a repeatable project brief</h2><p>After reviewing a sample, write down the selected SKU, base, fixing method and the number of pieces used per finished project. An illustrative ten-project plan using one decoration on each base calls for ten decorations; that planning count does not change the supplier's pack or MOQ. Add separately confirmed hardware and any extras your own packing process needs.</p><p>For a workshop, retail kit or handmade collection, send the same brief with your inquiry: project photo or sketch, selected product codes, desired number of finished items, quantities and units, destination, and packing requirements. If consistent color balance or matching pairs matter, make that explicit before confirming a mixed assortment. See <a href="guide-diy-craft-kit-components.html">how to brief a DIY craft kit</a> and <a href="guide-craft-supply-packaging.html">packing options for craft supplies</a>.</p></section>
<section id="questions"><h2>Questions before choosing ready-made resin charms</h2><h3>Can every resin charm be attached with a jump ring?</h3><p>No. A jump ring needs a suitable confirmed hole, loop or separate connector. Flatback decorations require another appropriate mounting route. Check the exact SKU and hardware dimensions.</p><h3>Can I choose individual cookie designs from RW22372?</h3><p>The standard bag is a random mixed assortment; individual designs and colors cannot be selected. Send any matching-pair or custom-assortment requirement for a separate feasibility review.</p><h3>What should I send when asking about materials for my project?</h3><p>Send product codes, the intended project, base or mounting method, quantity and unit, destination and packing requirements. Include the reverse-side, thickness or connection dimensions you still need confirmed.</p></section>
<div class="guide-note"><h2>Choose materials for your next project</h2><p>Browse the <a href="resin-charms.html">resin charms catalog</a>, shortlist the shapes you need, and send your project brief. We will review the selected components and order requirements with you.</p><a class="btn btn-primary" data-diy-project-inquiry href="[[PROJECT_INQUIRY]]">Discuss your resin charm project</a></div>
</article></section>'''

for token,sku,project in [('COOKIE_CARD','RW22372','Cookie hair clip: please confirm bonding area, thickness and a suitable assembly method'),('CANDY_CARD','RW4252','Candy-theme bag charm: please confirm reverse side and carrier/mounting requirements'),('RING_CARD','CDK070','Bag charm/keychain hardware: please confirm ring and connector dimensions'),('BOW_CARD','RW26898','Gift decoration: please confirm reverse side, fixing method and packing')]:
 body=body.replace('[['+token+']]',card(sku,project))
body=body.replace('[[FACT_ROWS]]',''.join(f'<tr><td><a href="{PRODUCTS[sku]["pdp"]}">{sku} — {esc(v[0])}</a></td><td>{esc(v[1])}</td><td>{esc(v[2])}</td><td>{esc(v[3])}</td></tr>' for sku,v in FACTS.items()))
project_params=dict(source='ready-made-resin-diy',category='Resin Charms',product='Ready-made resin charm project',entry_page='/'+SLUG,application='DIY ready-made resin charm project: please review selected SKUs, mounting method, sample needs, quantity/unit, destination and packing.')
body=body.replace('[[PROJECT_INQUIRY]]',esc('quote.html?'+urlencode(project_params)))
shell=(ROOT/'guide-diy-craft-kit-components.html').read_text()
head=shell[:re.search(r'<main[^>]*>',shell).end()]
head=re.sub(r'<script type="application/ld\+json">.*?</script>\s*','',head,flags=re.S)
head=re.sub(r'<title>.*?</title>','<title>'+TITLE+'</title>',head,count=1,flags=re.S)
url=BASE+SLUG;cover=BASE+PRODUCTS['RW26898']['image']
for name,value in {'description':DESCRIPTION,'og:title':TITLE,'og:description':DESCRIPTION,'og:url':url,'og:image':cover,'twitter:title':TITLE,'twitter:description':DESCRIPTION,'twitter:image':cover}.items():
 pattern=r'(<meta (?:name|property)="'+re.escape(name)+r'" content=")[^"]*(")'
 if re.search(pattern,head):head=re.sub(pattern,lambda m:m[1]+esc(value)+m[2],head)
 elif name.startswith('twitter:'):head=head.replace('</head>',f'<meta name="{name}" content="{esc(value)}">\n</head>')
head=re.sub(r'(<link rel="canonical" href=")[^"]*(")',lambda m:m[1]+url+m[2],head)
head=re.sub(r'(hreflang="[^"]*" href=")[^"]*(")',lambda m:m[1]+url+m[2],head)
head=head.replace('</head>','<link rel="stylesheet" href="assets/css/ready-made-resin-diy.css?v=20261108">\n</head>')
article={'@context':'https://schema.org','@type':'Article','headline':TITLE,'description':DESCRIPTION,'image':cover,'datePublished':DATE,'dateModified':DATE,'mainEntityOfPage':url,'inLanguage':'en','author':{'@type':'Organization','@id':BASE+'#organization','name':'Qula Craft','url':BASE,'logo':BASE+'assets/images/favicon.png'},'publisher':{'@type':'Organization','name':'Qula Craft','logo':{'@type':'ImageObject','url':BASE+'assets/images/favicon.png'}}}
crumb={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':name,'item':link}for i,(name,link) in enumerate([('Home',BASE),('Resources',BASE+'resources.html'),(TITLE,url)])]}
head=head.replace('</head>',''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False).replace('<','\\u003c')+'</script>\n' for s in [article,crumb])+'</head>')
(ROOT/SLUG).write_text(head+body+shell[shell.index('</main>'):])

# Idempotent, narrow inbound links. Existing product cards and buying answers stay intact.
p=ROOT/'resources.html';s=p.read_text();s=re.sub(r'<!-- ready-made-resin-guide:start -->.*?<!-- ready-made-resin-guide:end -->','',s,flags=re.S)
entry=f'<!-- ready-made-resin-guide:start --><article class="article-card"><span>DIY Projects · Ready-Made Charms</span><h3>{TITLE}</h3><p>Plan hair clips, bag charms and gift decorations with real resin SKUs, size and packing references, and clear attachment checks.</p><a href="{SLUG}">Choose a resin charm project →</a></article><!-- ready-made-resin-guide:end -->'
assert '<div class="article-grid">' in s;s=s.replace('<div class="article-grid">','<div class="article-grid">'+entry,1);p.write_text(s)
p=ROOT/'resin-charms.html';s=p.read_text();s=re.sub(r'<!-- ready-made-resin-link:start -->.*?<!-- ready-made-resin-link:end -->','',s,flags=re.S)
needle='<a class="text-link" href="guide-decoden-supplies.html">Choose charms for a phone case</a>';assert needle in s
s=s.replace(needle,needle+f'<!-- ready-made-resin-link:start --> &middot; <a class="text-link" href="{SLUG}">DIY projects with ready-made resin charms</a><!-- ready-made-resin-link:end -->',1);p.write_text(s)
p=ROOT/'llms.txt';s=p.read_text();line=f'- [{TITLE}]({url}): Hair clips, bag charms and gift decorations using ready-made components; four real catalog references, packing units and attachment checks.'
s='\n'.join(x for x in s.splitlines() if SLUG not in x).rstrip()+'\n\n'+line+'\n';p.write_text(s)
p=ROOT/'sitemap.xml';s=p.read_text()
if url not in s:s=s.replace('</urlset>',f'  <url><loc>{url}</loc><lastmod>{DATE}</lastmod></url>\n</urlset>')
for changed in ['resources.html','resin-charms.html']:
 pattern=r'(<url>\s*<loc>'+re.escape(BASE+changed)+r'</loc>\s*<lastmod>)[^<]+(</lastmod>)'
 s,n=re.subn(pattern,lambda m:m[1]+DATE+m[2],s);assert n==1,changed
p.write_text(s)
print('Built',SLUG,'with 4 existing SKU references, 3 project paths and inbound links.')
